// Package parity_test checks the Go port against fixtures generated by the
// TypeScript itself.
//
// This is deliberately NOT a normal unit test. A unit test written by whoever
// wrote the port proves only that the port matches that person's reading of the
// original; if the reading is wrong, the test agrees and everything stays green.
// Here the expected values come from tools/parity/fixtures.json, which is
// produced by executing the real src/*.ts (see gen_fixtures.mjs). A failure here
// therefore means the Go behaviour differs from the shipped TypeScript.
package parity_test

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"

	"blore/internal/fts"
	"blore/internal/sandbox"
)

type ftsCase struct {
	Input string `json:"input"`
	Want  string `json:"want"`
}

type sandboxCase struct {
	Input     string  `json:"input"`
	Want      *string `json:"want"`
	WantError *string `json:"wantError"`
}

type fixtures struct {
	BasePath string        `json:"basePath"`
	Fts      []ftsCase     `json:"fts"`
	Sandbox  []sandboxCase `json:"sandbox"`
}

func load(t *testing.T) fixtures {
	t.Helper()
	path := filepath.Join("..", "..", "tools", "parity", "fixtures.json")
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("cannot read fixtures (%s): %v\n"+
			"regenerate with: bun run server-go/tools/parity/gen_fixtures.mjs", path, err)
	}
	var f fixtures
	if err := json.Unmarshal(raw, &f); err != nil {
		t.Fatalf("fixtures are not valid JSON: %v", err)
	}
	// A fixture file that parsed but is empty would make every loop below pass
	// vacuously, which is the classic way a parity suite quietly stops testing.
	if len(f.Fts) == 0 || len(f.Sandbox) == 0 {
		t.Fatalf("fixtures look empty (fts=%d sandbox=%d); refusing to report success",
			len(f.Fts), len(f.Sandbox))
	}
	return f
}

func TestBuildQueryMatchesTypeScript(t *testing.T) {
	f := load(t)
	for _, c := range f.Fts {
		got := fts.BuildQuery(c.Input)
		if got != c.Want {
			t.Errorf("BuildQuery(%q)\n  go  = %q\n  ts  = %q", c.Input, got, c.Want)
		}
	}
	t.Logf("compared %d buildFtsQuery cases against the TypeScript output", len(f.Fts))
}

func TestValidateAndResolveMatchesTypeScript(t *testing.T) {
	f := load(t)
	// The fixture's basePath was resolved by the TS PathSandbox from an absolute
	// path, so pass it through as absolute and assert the Go side agrees on it.
	s := sandbox.New(`D:\repo`, f.BasePath)
	if s.BasePath() != f.BasePath {
		t.Errorf("basePath: go = %q, ts = %q", s.BasePath(), f.BasePath)
	}

	checked := 0
	rejections := 0
	for _, c := range f.Sandbox {
		got, err := s.ValidateAndResolve(c.Input)
		checked++

		switch {
		case c.WantError != nil:
			rejections++
			if err == nil {
				t.Errorf("ValidateAndResolve(%q): go accepted, ts rejected with %q", c.Input, *c.WantError)
				continue
			}
			// Message parity matters as much as accept/reject parity: callers and
			// tests compare these strings, and a Go %q would double Windows
			// backslashes where the TS template literal does not.
			if err.Error() != *c.WantError {
				t.Errorf("ValidateAndResolve(%q) error text differs\n  go = %q\n  ts = %q",
					c.Input, err.Error(), *c.WantError)
			}
		default:
			if err != nil {
				t.Errorf("ValidateAndResolve(%q): go rejected (%v), ts accepted with %q",
					c.Input, err, *c.Want)
				continue
			}
			if got != *c.Want {
				t.Errorf("ValidateAndResolve(%q)\n  go = %q\n  ts = %q", c.Input, got, *c.Want)
			}
		}
	}
	t.Logf("compared %d validateAndResolve cases (%d of them rejections) against the TypeScript",
		checked, rejections)

	// Guard against a corpus that stopped exercising the rejection path: the whole
	// point of the 2026-10-14 fix was that cross-drive and UNC paths are refused.
	if rejections == 0 {
		t.Error("no rejection cases in the corpus — the sandbox gates are not being exercised")
	}
}
